850	///
851	/// Tasks registering a new subject read these while transcribing fixtures, so
852	/// the message carries what to look at, not just what failed.
853	fn fail(subject: &str, scenario: Scenario, violation: &Violation, detail: &str) -> ! {
854	    panic!("conformance: {subject} / {scenario:?} — {violation:?}\n  {detail}");
855	}
