857	/// A one-line summary of what a stream emitted, for failure output.
858	fn summarise(events: &[Result<ModelEvent, ModelError>]) -> String {
859	    if events.is_empty() {
860	        return "<nothing>".to_owned();
861	    }
862	    events
863	        .iter()
864	        .map(|event| match event {
865	            Ok(ModelEvent::TokenDelta { .. }) => "TokenDelta".to_owned(),
866	            Ok(ModelEvent::ReasoningDelta { .. }) => "ReasoningDelta".to_owned(),
867	            Ok(ModelEvent::ToolCallDelta { call_id, name, .. }) => match name {
868	                Some(name) => format!("ToolCallDelta({call_id}, name={name})"),
869	                None => format!("ToolCallDelta({call_id})"),
870	            },
871	            Ok(ModelEvent::Usage { .. }) => "Usage".to_owned(),
872	            Ok(ModelEvent::Finish { reason }) => format!("Finish({reason:?})"),
873	            Ok(other) => format!("{other:?}"),
874	            Err(err) => format!("Err({err:?})"),
875	        })
876	        .collect::<Vec<_>>()
877	        .join(", ")
878	}
