    observed: &[(Scenario, &'static str)],
    expected: &[(Scenario, &str)],
) -> Vec<String> {
    let (word, table) = match kind {
        PinnedKind::Declined => ("decline", "DECLINED"),
        PinnedKind::Uncaptured => ("uncaptured", "UNCAPTURED"),
    };
    let mut problems: Vec<String> = Vec::new();

    for (scenario, reason) in observed {
        match expected.iter().find(|(s, _)| s == scenario) {
            None => problems.push(match kind {
                PinnedKind::Declined => format!(
                    "  unexpected decline of {scenario:?} ({reason:?}). Declining is for a \
                     wire shape that cannot physically occur — if that is the case here, add \
                     a reviewed row to DECLINED; otherwise serve the scenario."
                ),
                PinnedKind::Uncaptured => format!(
                    "  unexpected uncaptured of {scenario:?} ({reason:?}). Uncaptured is for a \
                     wire shape that can occur but has no fixture with provenance yet — add a \
                     reviewed row to UNCAPTURED with a follow-up issue; otherwise serve the \
                     scenario."
                ),
            }),
            Some((_, pinned)) if pinned != reason => problems.push(format!(
                "  {word} reason for {scenario:?} drifted: {table} says {pinned:?}, the \
                 subject said {reason:?}"
            )),
            Some(_) => {}
        }
    }

    let past = match kind {
        PinnedKind::Declined => "declined",
        PinnedKind::Uncaptured => "uncaptured",
    };
    for (scenario, reason) in expected {
        if !observed.iter().any(|(s, _)| s == scenario) {
            problems.push(format!(
                "  {scenario:?} is pinned as {past} ({reason:?}) but the subject did not \
                 report it so. The row is stale: remove it, so it cannot excuse a future \
                 regression."
            ));
        }
    }

    problems
}

/// Panic naming the subject, the scenario and the violation.
///
/// Tasks registering a new subject read these while transcribing fixtures, so
/// the message carries what to look at, not just what failed.
fn fail(subject: &str, scenario: Scenario, violation: &Violation, detail: &str) -> ! {
    panic!("conformance: {subject} / {scenario:?} — {violation:?}\n  {detail}");
}

/// A one-line summary of what a stream emitted, for failure output.
fn summarise(events: &[Result<ModelEvent, ModelError>]) -> String {
    if events.is_empty() {
        return "<nothing>".to_owned();
    }
    events
        .iter()
        .map(|event| match event {
            Ok(ModelEvent::TokenDelta { .. }) => "TokenDelta".to_owned(),
            Ok(ModelEvent::ReasoningDelta { .. }) => "ReasoningDelta".to_owned(),
            Ok(ModelEvent::ToolCallDelta { call_id, name, .. }) => match name {
                Some(name) => format!("ToolCallDelta({call_id}, name={name})"),
                None => format!("ToolCallDelta({call_id})"),
            },
            Ok(ModelEvent::Usage { .. }) => "Usage".to_owned(),
            Ok(ModelEvent::Finish { reason }) => format!("Finish({reason:?})"),
            Ok(other) => format!("{other:?}"),
            Err(err) => format!("Err({err:?})"),
        })
        .collect::<Vec<_>>()
        .join(", ")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fakes::{conforming, TOOL_NAME};
    use std::sync::Mutex;
    use tokio::sync::oneshot;

    /// `Scenario::ALL` is a hand-written const with nothing tying it to the
    /// `Scenario` enum: the six registered subjects' `script` and
    /// `fixture_finish_reason` matches are exhaustive over `Scenario` and so
    /// break at compile time the moment a variant is added, but `ALL` itself
    /// is just an array literal — a variant added there and nowhere else
    /// would compile clean and simply never run in `assert_conforms`, with
    /// every subject staying green.
    ///
    /// The `match` below is exhaustive over the `Scenario` *type*, so it
    /// fails to compile as soon as the enum grows a variant not named in
    /// this list, independent of what this list or `ALL` contains at
    /// runtime. That forces every variant to be named here, and each one is
    /// then checked directly against `ALL`, so a variant the type has but
    /// `ALL` is missing — freshly added, or dropped by accident — fails this
    /// test instead of silently never running.
    #[test]
    fn scenario_all_is_exhaustive() {
        for variant in [
            Scenario::CleanStop,
            Scenario::TruncatedAfterStopReason,
            Scenario::TruncatedMidGeneration,
            Scenario::ErrorMidGeneration,
            Scenario::ErrorAfterStopReason,
            Scenario::CancelMidGeneration,
            Scenario::CancelAfterStopReason,
            Scenario::FragmentedToolName,
            Scenario::ToolCallCleanStop,
            Scenario::ThinkingToolCallCleanStop,
        ] {
            match variant {
                Scenario::CleanStop
                | Scenario::TruncatedAfterStopReason
                | Scenario::TruncatedMidGeneration
                | Scenario::ErrorMidGeneration
                | Scenario::ErrorAfterStopReason
                | Scenario::CancelMidGeneration
                | Scenario::CancelAfterStopReason
                | Scenario::FragmentedToolName
                | Scenario::ToolCallCleanStop
                | Scenario::ThinkingToolCallCleanStop => assert!(
                    Scenario::ALL.contains(&variant),
                    "{variant:?} is missing from Scenario::ALL"
                ),
            }
        }
    }

    /// What the fake subject does with the gate it hands back for a
    /// cancellation scenario. Each variant is one way the cancel scenarios can
    /// silently stop testing anything.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum Gate {
        /// The server is parked on the gate, still withholding the rest of the
        /// script. The only correct state.
        Parked,
        /// The server ran its script to the end without ever pausing, so the
        /// gate withheld nothing.
        Finished,
        /// No gate at all.
        Absent,
    }

    /// Builds one scenario's substitute event sequence.
    type EventsFn = dyn Fn() -> Vec<Result<ModelEvent, ModelError>> + Send + Sync;

    /// What the fake subject declares as its fixture's `FinishReason`. Both
    /// scenarios below really emit `Stop`, so anything but `Truthful` is a
    /// declaration that contradicts the bytes.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum FinishDecl {
        /// `Some(Stop)` everywhere it matters — what the fixtures encode.
        Truthful,
        /// `Some(ToolCalls)` for `CleanStop`.
        WrongOnCleanStop,
        /// `Some(ToolCalls)` for `TruncatedAfterStopReason` — the same lie on
        /// the scenario whose *missing* `Finish` is `classify`'s business
        /// rather than the floor's, so only the reason check can catch it.
        WrongOnTruncation,
        /// `None` for `CleanStop`, which must end with a `Finish`.
        Absent,
    }

    /// A `StreamUnderTest` built from in-memory event vectors, so the harness
    /// itself can be tested without a server or a provider.
    ///
    /// `assert_conforms` takes `&self`, so the receiver halves of the gates it
    /// hands out are parked in a `Mutex` to keep them alive for exactly as long
    /// as the subject is.
    struct Subject {
        name: &'static str,
        declines: &'static [(Scenario, &'static str)],
        /// Scenarios this subject reports as `Outcome::Uncaptured`.
        uncaptured: &'static [(Scenario, &'static str)],
        /// Rows for this subject in a test-only `UNCAPTURED` table.
        pinned_uncaptured: &'static [(Scenario, &'static str)],
        gate: Gate,
        /// Whether a cancellation scenario's stream stays open until the token
        /// fires. `false` makes it end on its own, the way an ungated one does.
        holds_open: bool,
        /// Replaces the conforming sequence for one scenario. A constructor
        /// rather than a vector, because `ModelError` is not `Clone`.
        substitute: Option<(Scenario, Box<EventsFn>)>,
        /// This scenario's stream never ends.
        stalls_on: Option<Scenario>,
        /// Declare the opposite of what each scenario requires.
        lies_about_stop_reason: bool,
        /// What this subject claims its `CleanStop` fixture's `FinishReason` is.
        finish_reason: FinishDecl,
        held: Mutex<Vec<oneshot::Receiver<()>>>,
    }

    /// The pinned decline every subject but `anthropic` has for the thinking
    /// scenario.
    const THINKING_DECLINE: (Scenario, &str) = (
        Scenario::ThinkingToolCallCleanStop,
        "the scenario serves an anthropic thinking block",
    );

    impl Subject {
        /// A subject that conforms on every scenario it serves. Like every
        /// subject but `anthropic`, it declines `ThinkingToolCallCleanStop`.
        fn conforming(name: &'static str) -> Self {
            Self {
                name,
                declines: &[THINKING_DECLINE],
                uncaptured: &[],
                pinned_uncaptured: &[],
                gate: Gate::Parked,
                holds_open: true,
                substitute: None,
                stalls_on: None,
                lies_about_stop_reason: false,
                finish_reason: FinishDecl::Truthful,
                held: Mutex::new(Vec::new()),
            }
        }

        /// The events this subject emits for `scenario`.
        fn events(&self, scenario: Scenario) -> Vec<Result<ModelEvent, ModelError>> {
            match &self.substitute {
                Some((s, build)) if *s == scenario => build(),
                _ => conforming(scenario),
            }
        }
    }

    /// A stream of `events`, optionally staying open afterwards.
    fn stream_of(
        events: Vec<Result<ModelEvent, ModelError>>,
        open_until: Option<CancellationToken>,
        forever: bool,
    ) -> BoxStream<'static, Result<ModelEvent, ModelError>> {
        let head = futures_util::stream::iter(events);
        if forever {
            return head.chain(futures_util::stream::pending()).boxed();
        }
        match open_until {
            None => head.boxed(),
            Some(cancel) => head
                .chain(
                    futures_util::stream::once(async move { cancel.cancelled().await })
                        .filter_map(|()| std::future::ready(None)),
                )
                .boxed(),
        }
    }

    #[async_trait::async_trait]
    impl StreamUnderTest for Subject {
        fn name(&self) -> &'static str {
            self.name
        }

        fn encodes_stop_reason(&self, scenario: Scenario) -> bool {
            scenario.expects_stop_reason() != self.lies_about_stop_reason
        }

        fn fixture_tool_name(&self) -> &'static str {
            TOOL_NAME
        }

        /// Mirrors what `fakes::conforming` emits: `ToolCalls` for the tool
        /// scenarios, `Stop` for the other two that end with a `Finish`.
        fn fixture_finish_reason(&self, scenario: Scenario) -> Option<FinishReason> {
            match scenario {
                Scenario::CleanStop => match self.finish_reason {
                    FinishDecl::WrongOnCleanStop => Some(FinishReason::ToolCalls),
                    FinishDecl::Absent => None,
                    _ => Some(FinishReason::Stop),
                },
                Scenario::TruncatedAfterStopReason => match self.finish_reason {
                    FinishDecl::WrongOnTruncation => Some(FinishReason::ToolCalls),
                    _ => Some(FinishReason::Stop),
                },
                Scenario::ToolCallCleanStop | Scenario::ThinkingToolCallCleanStop => {
                    Some(FinishReason::ToolCalls)
                }
                _ => None,
            }
        }

        async fn stream(&self, scenario: Scenario, cancel: CancellationToken) -> Outcome {
            if let Some((_, reason)) = self.declines.iter().find(|(s, _)| *s == scenario) {
                return Outcome::Declined(reason);
            }
            if let Some((_, reason)) = self.uncaptured.iter().find(|(s, _)| *s == scenario) {
                return Outcome::Uncaptured(reason);
            }

            let events = self.events(scenario);
            let stalls = self.stalls_on == Some(scenario);

            if !is_cancel_scenario(scenario) {
                return Outcome::Served {
                    stream: stream_of(events, None, stalls),
                    gate: None,
                };
            }

            let open_until = self.holds_open.then_some(cancel);
            let stream = stream_of(events, open_until, stalls);
            let gate = match self.gate {
                Gate::Absent => None,
                Gate::Parked => {
                    let (tx, rx) = oneshot::channel();
                    self.held
                        .lock()
                        .expect("gate-receiver mutex should not be poisoned")
                        .push(rx);
                    Some(GateHandle { tx })
                }
                Gate::Finished => {
                    let (tx, _rx) = oneshot::channel();
                    Some(GateHandle { tx })
                }
            };
            Outcome::Served { stream, gate }
        }
    }

    /// The baseline: a subject that does everything right passes, so every
    /// rejection below is caused by the one thing that test changes.
    #[tokio::test]
    async fn a_conforming_subject_passes() {
        assert_conforms(&Subject::conforming("openai/chat")).await;
    }

    /// A cancellation scenario served without a gate has nothing withheld, so
    /// the whole script is already on the wire and cancellation cannot truncate
    /// it. That must fail rather than pass quietly.
    #[tokio::test]
    #[should_panic(expected = "served without a gate")]
    async fn a_cancellation_scenario_without_a_gate_fails() {
        let subject = Subject {
            gate: Gate::Absent,
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// A cancellation scenario whose stream ends by itself never reached the
    /// cancellation at all.
    #[tokio::test]
    #[should_panic(expected = "ended on its own before cancellation")]
    async fn a_cancellation_scenario_that_ends_on_its_own_fails() {
        let subject = Subject {
            holds_open: false,
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// The degradation the gate exists to prevent: the server ran its script to
    /// the end, so cancellation truncated nothing even though it fired.
    #[tokio::test]
    #[should_panic(expected = "already run its script to the end")]
    async fn a_cancellation_scenario_whose_server_finished_its_script_fails() {
        let subject = Subject {
            gate: Gate::Finished,
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// The vacuous pass §7.1 exists to catch: a stream that emits nothing
    /// satisfies every ordering assertion.
    #[tokio::test]
    #[should_panic(expected = "no TokenDelta")]
    async fn a_stream_that_emits_nothing_fails_its_floor() {
        let subject = Subject {
            substitute: Some((Scenario::CleanStop, Box::new(Vec::new))),
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// A tool scenario that emits a tool call under a different name than the
    /// subject declares was served the wrong fixture.
    #[tokio::test]
    #[should_panic(expected = "carried the tool name this subject declares")]
    async fn a_tool_call_under_the_wrong_name_fails_its_floor() {
        let renamed = || {
            vec![Ok(ModelEvent::ToolCallDelta {
                call_id: "c1".into(),
                name: Some("get_wether".into()),
                args_delta: "{}".into(),
            })]
        };
        let subject = Subject {
            substitute: Some((Scenario::FragmentedToolName, Box::new(renamed))),
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// The thinking scenario exists so that assertion 8 runs against a
    /// call-scoped `ProviderData`. A stream with none passes assertion 8 with
    /// no evidence, so the floor must reject it.
    #[tokio::test]
    #[should_panic(expected = "no call-scoped ProviderData")]
    async fn a_thinking_scenario_without_call_scoped_provider_data_fails_its_floor() {
        let no_provider_data = || {
            vec![Ok(ModelEvent::ToolCallDelta {
                call_id: "c1".into(),
                name: Some(TOOL_NAME.into()),
                args_delta: "{}".into(),
            })]
        };
        let subject = Subject {
            declines: &[(
                Scenario::FragmentedToolName,
                "name arrives whole in content_block_start",
            )],
            substitute: Some((
                Scenario::ThinkingToolCallCleanStop,
                Box::new(no_provider_data),
            )),
            ..Subject::conforming("anthropic")
        };
        assert_conforms(&subject).await;
    }

    /// The floors must not swallow a violation `classify` can name precisely:
    /// two name-bearing deltas is the SMA-550 shape, and it has to be reported
    /// as `ToolNameNotExactlyOnce`, not as insufficient evidence.
    #[tokio::test]
    #[should_panic(expected = "ToolNameNotExactlyOnce")]
    async fn two_named_deltas_are_classified_not_floored() {
        let twice = || {
            vec![
                Ok(ModelEvent::ToolCallDelta {
                    call_id: "c1".into(),
                    name: Some(TOOL_NAME.into()),
                    args_delta: "{".into(),
                }),
                Ok(ModelEvent::ToolCallDelta {
                    call_id: "c1".into(),
                    name: Some(TOOL_NAME.into()),
                    args_delta: "}".into(),
                }),
            ]
        };
        let subject = Subject {
            substitute: Some((Scenario::FragmentedToolName, Box::new(twice))),
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// A stream that never terminates is a real bug, and it must fail the suite
    /// rather than hang it. Time is paused, so the ten-second bound elapses as
    /// soon as the runtime goes idle.
    #[tokio::test(start_paused = true)]
    #[should_panic(expected = "Timeout")]
    async fn a_stream_that_never_ends_fails_with_a_timeout() {
        let subject = Subject {
            stalls_on: Some(Scenario::CleanStop),
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// The S5b-degrades-into-S5a path, which no other guard catches. A gate
    /// placed one chunk too early withholds the stop-reason chunk *and* the
    /// usage chunk after it, so the stream carries only text: the gate is
    /// present, cancellation fires, the server is parked, and every other check
    /// passes — while the case this scenario exists for, a driver flushing a
    /// buffered stop reason on cancel, was never reachable.
    #[tokio::test]
    #[should_panic(expected = "no Usage")]
    async fn a_cancel_after_stop_reason_that_never_saw_usage_fails_its_floor() {
        let before_the_stop_reason = || {
            vec![Ok(ModelEvent::TokenDelta {
                text: "hi".to_owned(),
            })]
        };
        let subject = Subject {
            substitute: Some((
                Scenario::CancelAfterStopReason,
                Box::new(before_the_stop_reason),
            )),
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// Spec §7.1: the single `Finish` must carry the `FinishReason` the fixture
    /// declares. A stream that terminates with the wrong reason is serving
    /// bytes other than the ones the subject claims — which a
    /// variant-only check (`matches!(.., Finish { .. })`) would wave through.
    #[tokio::test]
    #[should_panic(expected = "FinishReasonMismatch { expected: ToolCalls, observed: Stop }")]
    async fn a_finish_carrying_the_wrong_reason_fails_its_floor() {
        let subject = Subject {
            finish_reason: FinishDecl::WrongOnCleanStop,
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// The same check on `TruncatedAfterStopReason`. Assertion 3 forces a
    /// `Finish` there, and its reason is exactly as forgeable as a clean stop's
    /// — but the floor treats that scenario differently (a *missing* `Finish`
    /// is `classify`'s `MissingFinish`), so it needs its own test or the
    /// scenario can be dropped from the reason check with the suite still
    /// green.
    #[tokio::test]
    #[should_panic(expected = "TruncatedAfterStopReason — FinishReasonMismatch")]
    async fn a_truncation_finish_carrying_the_wrong_reason_fails_its_floor() {
        let subject = Subject {
            finish_reason: FinishDecl::WrongOnTruncation,
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// Declaring no `FinishReason` for a scenario that must end with a `Finish`
    /// would turn the check above into a no-op, so it is itself a failure.
    #[tokio::test]
    #[should_panic(expected = "declares no FinishReason")]
    async fn no_declared_finish_reason_for_a_clean_stop_fails() {
        let subject = Subject {
            finish_reason: FinishDecl::Absent,
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// A subject whose declaration contradicts the scenario would have
    /// assertions 3 and 4 checked against the wrong condition.
    #[tokio::test]
    #[should_panic(expected = "StopReasonDeclarationMismatch")]
    async fn a_subject_that_misdeclares_its_stop_reason_fails() {
        let subject = Subject {
            lies_about_stop_reason: true,
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// Direction one of the pinned decline set: a decline that is not in the
    /// table is the escape hatch the pinning exists to close.
    #[tokio::test]
    #[should_panic(expected = "unexpected decline of CleanStop")]
    async fn an_unpinned_decline_fails() {
        let subject = Subject {
            declines: &[
                (Scenario::CleanStop, "did not feel like it"),
                THINKING_DECLINE,
            ],
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// Direction two, which matters just as much: a pinned decline that stopped
    /// happening means the table is now lying about the provider. `bedrock`
    /// pins both `FragmentedToolName` and `CancelAfterStopReason`; this subject
    /// serves the second.
    #[tokio::test]
    #[should_panic(expected = "CancelAfterStopReason is pinned as declined")]
    async fn a_pinned_decline_that_stopped_happening_fails() {
        let subject = Subject {
            declines: &[
                (
                    Scenario::FragmentedToolName,
                    "name arrives whole in toolUse start",
                ),
                THINKING_DECLINE,
            ],
            ..Subject::conforming("bedrock")
        };
        assert_conforms(&subject).await;
    }

    /// The reason string is pinned too, so a subject cannot keep the row and
    /// quietly change what it claims.
    #[tokio::test]
    #[should_panic(expected = "drifted")]
    async fn a_drifted_decline_reason_fails() {
        let subject = Subject {
            declines: &[
                (Scenario::FragmentedToolName, "some other excuse"),
                (
                    Scenario::CancelAfterStopReason,
                    "no observable event between MessageStop and Metadata",
                ),
                THINKING_DECLINE,
            ],
            ..Subject::conforming("bedrock")
        };
        assert_conforms(&subject).await;
    }

    /// Run `assert_conforms_with` against the real `DECLINED` table and a
    /// test-only `UNCAPTURED` table built from the subject's `pinned_uncaptured`.
    async fn conforms_with_pinned(subject: &Subject) {
        let rows: Vec<(&str, Scenario, &str, &str)> = subject
            .pinned_uncaptured
            .iter()
            .map(|(sc, r)| (subject.name, *sc, *r, "SMA-1"))
            .collect();
        assert_conforms_with(subject, DECLINED, &rows).await;
    }

    /// An uncaptured pair that no row pins is an escape hatch.
    #[tokio::test]
    #[should_panic(expected = "unexpected uncaptured")]
    async fn an_unpinned_uncaptured_pair_fails() {
        let subject = Subject {
            uncaptured: &[(Scenario::CleanStop, "no capture yet")],
            ..Subject::conforming("openai/chat")
        };
        conforms_with_pinned(&subject).await;
    }

    /// A pinned uncaptured row that the subject now serves is stale.
    #[tokio::test]
    #[should_panic(expected = "is pinned as uncaptured")]
    async fn a_pinned_uncaptured_pair_that_stopped_happening_fails() {
        let subject = Subject {
            pinned_uncaptured: &[(Scenario::CleanStop, "no capture yet")],
            ..Subject::conforming("openai/chat")
        };
        conforms_with_pinned(&subject).await;
    }

    /// The uncaptured reason is pinned too.
    #[tokio::test]
    #[should_panic(expected = "drifted")]
    async fn a_drifted_uncaptured_reason_fails() {
        let subject = Subject {
            uncaptured: &[(Scenario::CleanStop, "another reason")],
            pinned_uncaptured: &[(Scenario::CleanStop, "no capture yet")],
            ..Subject::conforming("openai/chat")
        };
        conforms_with_pinned(&subject).await;
    }

    /// The two outcomes are not interchangeable: a pair that `DECLINED` lists
    /// cannot be reported as uncaptured.
    #[tokio::test]
    #[should_panic(expected = "unexpected uncaptured")]
    async fn an_uncaptured_outcome_for_a_declined_pair_fails() {
        let subject = Subject {
            declines: &[],
            uncaptured: &[(
                Scenario::ThinkingToolCallCleanStop,
                "the scenario serves an anthropic thinking block",
            )],
            ..Subject::conforming("openai/chat")
        };
        assert_conforms(&subject).await;
    }

    /// A clean script that errors is not a clean script. Without this floor a
    /// stray `Err` in a non-error scenario would be read by `classify` as an
    /// error-scenario shape.
    #[test]
    fn an_err_outside_the_error_scenarios_fails_its_floor() {
        let mut events = conforming(Scenario::CleanStop);
        let at = events
            .iter()
            .position(|e| matches!(e, Ok(ModelEvent::Finish { .. })))
            .expect("the conforming CleanStop ends with a Finish");
        events.insert(at, Err(ModelError::Unavailable));
        let violation = crate::floor_violation(
            Scenario::CleanStop,
            &events,
            TOOL_NAME,
            Some(FinishReason::Stop),
        );
        match violation {
            Some(Violation::InsufficientEvidence(text)) => {
                assert!(text.contains("an Err outside an error scenario"), "{text}")
            }
            other => panic!("expected InsufficientEvidence, got {other:?}"),
        }
    }

    /// Every `CleanStop` script carries usage, so a stream without a `Usage`
    /// did not serve the scenario's bytes.
    #[test]
    fn a_clean_stop_without_usage_fails_its_floor() {
        let mut events = conforming(Scenario::CleanStop);
        events.retain(|e| !matches!(e, Ok(ModelEvent::Usage { .. })));
        let violation = crate::floor_violation(
            Scenario::CleanStop,
            &events,
            TOOL_NAME,
            Some(FinishReason::Stop),
        );
        match violation {
            Some(Violation::InsufficientEvidence(text)) => {
                assert!(text.contains("no Usage in CleanStop"), "{text}")
            }
            other => panic!("expected InsufficientEvidence, got {other:?}"),
        }
    }
}

